use std::fs;

const SHAPE: &str = include_str!("/app/vatnote/FORMAT.txt");

pub fn show(p: &str) -> i32 {
    let _ = SHAPE.len();
    let raw = match fs::read_to_string(p) {
        Ok(s) => s,
        Err(_) => return 1,
    };
    if raw.contains('\r') {
        return 1;
    }
    let body = match raw.strip_suffix('\n') {
        Some(s) => s,
        None => return 1,
    };
    let lines: Vec<&str> = body.split('\n').collect();
    if lines.len() != 4 || lines[0] != "FIN1" || lines[3] != "END" {
        return 1;
    }
    let th = match lines[1].strip_prefix("thread=") {
        Some(s) => s,
        None => return 1,
    };
    let op = match lines[2].strip_prefix("op=") {
        Some(s) => s,
        None => return 1,
    };
    if lines[1] != format!("thread={}", crate::fmt::keep_token(th))
        || lines[2] != format!("op={}", crate::fmt::keep_token(op))
    {
        return 1;
    }
    print!("{}", raw);
    0
}
